create extension if not exists vector;

create table if not exists documents (
  id        bigserial primary key,
  content   text,
  metadata  jsonb,
  embedding vector(3072)
);

create or replace function match_documents (
  query_embedding vector(3072),
  match_count int default 5,
  filter jsonb default '{}'
) returns table (id bigint, content text, metadata jsonb, similarity float)
language plpgsql as $$
begin
  return query
  select d.id, d.content, d.metadata,
         1 - (d.embedding <=> query_embedding) as similarity
  from documents d
  where d.metadata @> filter
  order by d.embedding <=> query_embedding
  limit match_count;
end;
$$;

create table if not exists document_rows (
  id         bigserial primary key,
  dataset_id text references document_metadata(id) on delete cascade,
  row_data   jsonb
);
create index if not exists idx_rows_dataset on document_rows (dataset_id);
create index if not exists idx_rows_data on document_rows using gin (row_data);

with cleanup as (
  delete from document_rows where dataset_id = $1
)
insert into document_rows (dataset_id, row_data)
select $1, value from jsonb_array_elements($2::jsonb);

