const rows = $input.all().map(i => i.json);
const text = rows.map(r =>
  '• *' + r.title + '*  _(' + r.shape + ')_\n' +
  (r.shape === 'tabular'
     ? '   ' + r.row_count + ' rows - `' + r.columns + '`\n'
     : '') +
  '   added ' + r.added + ' by ' + r.uploader
).join('\n');
return [{ json: { reply:
  '*Knowledge base - ' + rows.length + ' file(s)*\n\n' + text +
  '\n\nAsk about any of it with `/ask`' } }];

const rows = $input.all().map(i => i.json).filter(r => r.question);
if (!rows.length) {
  return [{ json: { reply:
    '*No gaps this week* — everything asked was answerable from the uploaded files. Either the notes are good, or nobody asked anything hard.' } }];
}
const text = rows.map((r, i) =>
  (i + 1) + '. ' + r.question + (r.asked > 1 ? '  _(asked ' + r.asked + '×)_' : '')
).join('\n');
return [{ json: { reply:
  '*Questions I could not answer this week*\n\n' + text +
  '\n\nThese are the gaps in our notes. Upload something that covers them.' } }];

const e = $input.first().json;
const wf   = e.workflow?.name || 'unknown workflow';
const node = e.execution?.lastNodeExecuted || 'unknown node';
const msg  = (e.execution?.error?.message || 'no message').slice(0, 500);
const url  = e.execution?.url || '';
return [{ json: { reply:
  '⚠️ *' + wf + '* failed\n\n' +
  'Node: `' + node + '`\n' +
  'Error: ' + msg + '\n\n' +
  (url ? url : 'Open n8n to see the execution.') } }];

const ALLOWED = {
  'application/pdf':'pdf',
  'text/csv':'tabular',
  'application/vnd.ms-excel':'tabular',
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet':'tabular'
};
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const mime = (j.mime_type || '').toLowerCase();
  const kind = ALLOWED[mime];

  if (!kind) {
    j.rejected = true;
    j.reject_reason = 'Unsupported file type: ' + mime +
      '\nI accept: pdf, csv, xlsx';
  } else if ((j.file_size || 0) > 20 * 1024 * 1024) {
    j.rejected = true;
    j.reject_reason = 'That file is over 20 MB — Telegram will not let me download it.';
  } else {
    j.rejected = false;
    j.kind = kind;
    const base = (j.file_name || 'file')
      .replace(/\.[^.]+$/, '').toLowerCase()
      .replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 40);
    j.file_id = base + '_' + Date.now().toString(36).slice(-4);
    const p = (j.caption || '').split('|');
    j.subject     = (p[0] || 'general').trim();
    j.description = (p[1] || j.file_name || '').trim();
    j.title       = j.subject + ' — ' + j.description;
  }
  out.push({ json: j, binary: item.binary });
}
return out;

