// Spreadsheets are never embedded. Rows -> document_rows, one summary -> metadata.
const g = $('Guards - size, type, id').first().json;
const rows = $input.all().map(i => i.json);
const columns = rows.length ? Object.keys(rows[0]) : [];
return [{ json: {
  file_id: g.file_id, title: g.title, subject: g.subject,
  columns: columns.join(', '), row_count: rows.length,
  uploaded_by: g.uploaded_by, uploader: g.uploader, chat_id: g.chat_id,
  rows_json: JSON.stringify(rows)
}}];
